mapper.select:
SELECT TENANT_ID FROM PEACH_TENANT
WHERE ID = #{tenantRefId}
  AND STATUS = 'ENABLE' AND IS_DELETE = 0

mapper.update:
UPDATE PEACH_ORGANIZATION
SET PARENT_ORG_REF_ID = #{newParentRefId,jdbcType=VARCHAR},
    VERSION = VERSION + 1,
    MODIFY_TIME = DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'),
    MODIFIER_ID = #{modifierRefId}
WHERE ID = #{id}
  AND TENANT_ID = #{tenantBusinessId}
  AND VERSION = #{version}
  AND IS_DELETE = 0
